package backup

import (
	api "github.com/MateusMoutinhoOrg/AgnosTeset/sandbox/api"
	databasedeps "github.com/MateusMoutinhoOrg/AgnosTeset/sandbox/deps/databasedeps"
)

// This file is generated by `agnos build` from database.yaml — do not edit by hand.
//
// Every function takes the sandbox first, the way every function of
// sandbox/internal/ does. A search answers (record, false) when there is
// nothing to find and a write answers an error when something went wrong; no
// stored value is ever asserted into a type without checking, so a malformed
// record is an error rather than a panic.

// AddBlob inserts one blob record.
func AddBlob(sandbox *api.Sandbox, self *Backup, props BlobInput) (BlobRecord, error) {
	collection, err := sandbox.Deps.OpinionatedAgnosDatabase.Collection(self.database, "blob")
	if err != nil {
		return BlobRecord{}, err
	}
	record, failure := collection.Insert(newBlobFields(props))
	if failure != nil {
		return BlobRecord{}, sandbox.Deps.OpinionatedAgnosDatabase.Fail(failure)
	}
	return buildBlobRecord(sandbox, record)
}

// FindBlobById reads one blob record by its permanent id.
func FindBlobById(sandbox *api.Sandbox, self *Backup, id int64) (BlobRecord, bool) {
	collection, err := sandbox.Deps.OpinionatedAgnosDatabase.Collection(self.database, "blob")
	if err != nil {
		sandbox.Deps.StdDeps.Logf("FindBlobById: %s \n", err.Error())
		return BlobRecord{}, false
	}
	record, ok, failure := collection.FindByID(id)
	if failure != nil {
		sandbox.Deps.StdDeps.Logf("FindBlobById: %s \n", sandbox.Deps.OpinionatedAgnosDatabase.Fail(failure).Error())
		return BlobRecord{}, false
	}
	if !ok {
		return BlobRecord{}, false
	}
	built, err := buildBlobRecord(sandbox, record)
	if err != nil {
		sandbox.Deps.StdDeps.Logf("FindBlobById: %s \n", err.Error())
		return BlobRecord{}, false
	}
	return built, true
}

