// ListBlobs reads every blob record the filter keeps.
func ListBlobs(sandbox *api.Sandbox, self *Backup, filter BlobFilter) ([]BlobRecord, error) {
	collection, err := sandbox.Deps.OpinionatedAgnosDatabase.Collection(self.database, "blob")
	if err != nil {
		return nil, err
	}
	records, failure := collection.ListAll()
	if failure != nil {
		return nil, sandbox.Deps.OpinionatedAgnosDatabase.Fail(failure)
	}
	kept := []BlobRecord{}
	for _, record := range records {
		built, err := buildBlobRecord(sandbox, record)
		if err != nil {
			return nil, err
		}
		if !matchBlob(sandbox, built, filter) {
			continue
		}
		kept = append(kept, built)
	}
	return kept, nil
}

// ListBlobsPage reads up to limit blob records after the first offset, every one past them when limit is 0.
func ListBlobsPage(sandbox *api.Sandbox, self *Backup, offset int, limit int) ([]BlobRecord, error) {
	collection, err := sandbox.Deps.OpinionatedAgnosDatabase.Collection(self.database, "blob")
	if err != nil {
		return nil, err
	}
	records, failure := collection.List(offset+1, limit)
	if failure != nil {
		return nil, sandbox.Deps.OpinionatedAgnosDatabase.Fail(failure)
	}
	page := []BlobRecord{}
	for _, record := range records {
		built, err := buildBlobRecord(sandbox, record)
		if err != nil {
			return nil, err
		}
		page = append(page, built)
	}
	return page, nil
}

// CountBlob is how many blob records are live.
func CountBlob(sandbox *api.Sandbox, self *Backup) (int, error) {
	collection, err := sandbox.Deps.OpinionatedAgnosDatabase.Collection(self.database, "blob")
	if err != nil {
		return 0, err
	}
	records, failure := collection.ListAll()
	if failure != nil {
		return 0, sandbox.Deps.OpinionatedAgnosDatabase.Fail(failure)
	}
	return len(records), nil
}

// SetBlobSha writes a new sha on one blob record.
func SetBlobSha(sandbox *api.Sandbox, self *Backup, id int64, value string) error {
	collection, err := sandbox.Deps.OpinionatedAgnosDatabase.Collection(self.database, "blob")
	if err != nil {
		return err
	}
	record, ok, failure := collection.FindByID(id)
	if failure != nil {
		return sandbox.Deps.OpinionatedAgnosDatabase.Fail(failure)
	}
	if !ok {
		return sandbox.Deps.StdDeps.Errorf("blob %d not found", id)
	}
	return sandbox.Deps.OpinionatedAgnosDatabase.Fail(record.Update("sha", value))
}

// SetBlobValue writes a new value on one blob record.
func SetBlobValue(sandbox *api.Sandbox, self *Backup, id int64, value []byte) error {
	collection, err := sandbox.Deps.OpinionatedAgnosDatabase.Collection(self.database, "blob")
	if err != nil {
		return err
	}
	record, ok, failure := collection.FindByID(id)
	if failure != nil {
		return sandbox.Deps.OpinionatedAgnosDatabase.Fail(failure)
	}
	if !ok {
		return sandbox.Deps.StdDeps.Errorf("blob %d not found", id)
	}
	return sandbox.Deps.OpinionatedAgnosDatabase.Fail(record.Update("value", value))
}

// RemoveBlob deletes one blob record and everything nested under it.
func RemoveBlob(sandbox *api.Sandbox, self *Backup, id int64) error {
	collection, err := sandbox.Deps.OpinionatedAgnosDatabase.Collection(self.database, "blob")
	if err != nil {
		return err
	}
	record, ok, failure := collection.FindByID(id)
	if failure != nil {
		return sandbox.Deps.OpinionatedAgnosDatabase.Fail(failure)
	}
	if !ok {
		return sandbox.Deps.StdDeps.Errorf("blob %d not found", id)
	}
	return sandbox.Deps.OpinionatedAgnosDatabase.Fail(record.Remove())
}

// newBlobFields is one insert into blob as the stored field map.
func newBlobFields(props BlobInput) map[string]any {
	return map[string]any{
		"sha":   props.Sha,
		"value": props.Value,
	}
}

// buildBlobRecord reads one stored blob record back into its Go form.
// Every conversion is checked, so a value of the wrong type is an error rather
// than a panic.
func buildBlobRecord(sandbox *api.Sandbox, record databasedeps.Record) (BlobRecord, error) {
	built := BlobRecord{Id: record.ID}

	valueSha, err := sandbox.Deps.OpinionatedAgnosDatabase.ReadString(record, "sha")
	if err != nil {
		return built, err
	}
	built.Sha = valueSha

	valueValue, err := sandbox.Deps.OpinionatedAgnosDatabase.ReadBytes(record, "value")
	if err != nil {
		return built, err
	}
	built.Value = valueValue

	return built, nil
}

// matchBlob is one BlobFilter applied to one record. A zero value
// never filters, so an empty filter keeps everything.
func matchBlob(sandbox *api.Sandbox, item BlobRecord, filter BlobFilter) bool {
	if !sandbox.Deps.OpinionatedAgnosDatabase.TextMatches(item.Sha, filter.ShaStartsWith, filter.ShaEquals) {
		return false
	}
	if !sandbox.Deps.OpinionatedAgnosDatabase.BytesMatches(item.Value, filter.ValueStartsWith, filter.ValueEquals) {
		return false
	}
	return true
}
